-- Self-service clinic-unit administration with revisioned writes and audit.
alter table public.reda_units add column revision integer not null default 1 check(revision>0);
create table private.reda_unit_events(id bigint generated always as identity primary key,unit_id uuid not null,organization_id uuid not null,actor_id uuid not null references auth.users(id),action text not null check(action in('created','updated','member_added','member_updated')),before_state jsonb not null,after_state jsonb not null,created_at timestamptz not null default now(),foreign key(unit_id,organization_id)references public.reda_units(id,organization_id));
create index reda_unit_events_org on private.reda_unit_events(organization_id,created_at desc);alter table private.reda_unit_events enable row level security;revoke all on private.reda_unit_events from public,anon,authenticated;
create function private.reda_save_unit(p_id uuid,p_revision integer,p_name text,p_slug text,p_status text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=private.reda_live_actor();org uuid:=private.reda_request_organization();u public.reda_units%rowtype;before jsonb:='{}';begin if not private.reda_is_clinician_aal2()or not private.reda_can_manage_units(org,actor)then raise exception using errcode='42501',message='Adminbehörighet och MFA krävs.';end if;if length(trim(coalesce(p_name,'')))not between 1 and 100 or p_slug!~'^[a-z0-9][a-z0-9-]{1,49}$' or p_status not in('active','disabled')then raise exception using errcode='22023',message='Kontrollera enhetsuppgifterna.';end if;if p_id is null then insert into public.reda_units(organization_id,name,slug,status)values(org,trim(p_name),p_slug,p_status)returning * into u;insert into private.reda_unit_events(unit_id,organization_id,actor_id,action,before_state,after_state)values(u.id,org,actor,'created','{}',to_jsonb(u));else select * into u from public.reda_units where id=p_id and organization_id=org for update;if u.id is null then raise exception using errcode='42501',message='Enheten är inte tillgänglig.';end if;if p_revision<>u.revision then raise exception using errcode='40001',message='Enheten har ändrats. Uppdatera innan du sparar.';end if;before=to_jsonb(u);update public.reda_units set name=trim(p_name),slug=p_slug,status=p_status,revision=revision+1 where id=p_id returning * into u;insert into private.reda_unit_events(unit_id,organization_id,actor_id,action,before_state,after_state)values(u.id,org,actor,'updated',before,to_jsonb(u));end if;return to_jsonb(u);end$$;
create function public.reda_save_unit(p_id uuid,p_revision integer,p_name text,p_slug text,p_status text)returns jsonb language sql security invoker set search_path='' as $$select private.reda_save_unit(p_id,p_revision,p_name,p_slug,p_status)$$;
revoke all on function private.reda_save_unit(uuid,integer,text,text,text),public.reda_save_unit(uuid,integer,text,text,text) from public,anon,authenticated;grant execute on function private.reda_save_unit(uuid,integer,text,text,text),public.reda_save_unit(uuid,integer,text,text,text) to authenticated;
